const plugin = {
  id: "hello-gloom",
  name: "Hello Gloom",
  version: "0.1.0",
  description: "A minimal Gloom plugin.",
  toggleable: true,

  cliCommands: [
    {
      name: "hello",
      description: "Print a greeting",
      execute(args, ctx) {
        ctx.printResult({ data: { greeting: `hello ${args[0] ?? "gloom"}` } });
      },
    },
  ],

  setup(ctx) {
    ctx.registerCommand({
      id: "hello-gloom-command",
      label: "Hello Gloom",
      description: "Show a hello notification",
      keywords: ["hello", "demo"],
      category: "navigation",
      shortcut: "HELLO",
      execute: () => {
        ctx.notify({
          body: "Hello from your plugin.",
          type: "success",
        });
      },
    });
  },
};

export default plugin;

